import json,sys
from export_reports import export_reports
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]

def run():
    d=json.loads((ROOT/'reports/final.json').read_text());dev=json.loads((ROOT/'reports/development.json').read_text());audit=json.loads((ROOT/'reports/data_audit.json').read_text())
    score=d['metrics'];dec=d['decision'];b=dec['selected_baseline'];oper=d['operating'];names={'seasonal_naive':'Seasonal naive + residual quantiles','croston_sba':'Croston SBA + residual quantiles','global_quantiles':'Global quantile boosting'}
    improve=1-score['global_quantiles']['mean_pinball']/score[b]['mean_pinball'];cost_improve=1-oper['primary']['global_quantiles']['total_penalty']/oper['primary'][b]['total_penalty']
    md=['# Forecast accuracy and constrained inventory decisions','','17 October2026. Historical M5 research case. Final evaluation is frozen; there is no live replenishment deployment.','',
        '## Findings','',
        f"The fixed global model has final mean pinball loss {score['global_quantiles']['mean_pinball']:.6f}, versus {score[b]['mean_pinball']:.6f} for the development-selected {b} baseline: {improve:.2%} lower. The paired difference is {dec['paired_pinball_difference']:.6f}, with a two-origin moving-block bootstrap95% interval [{dec['bootstrap95'][0]:.6f}, {dec['bootstrap95'][1]:.6f}]. This conditions on the fitted models and fixed sample. Only15 weekly origins support the comparison;210 correlated series are not210 independent experiments.",
        '', 'Forecast and operating rankings differ among the baselines: seasonal naive has lower final pinball loss than Croston, while Croston has lower simulated holding-plus-lost-sales penalty in the primary operating case. The global model is best on both metrics in that case. This is an observed result of the fixed analysis, not a requirement imposed on model selection.','',
        f"The global model’s primary simulated penalty is USD {oper['primary']['global_quantiles']['total_penalty']:,.2f}, {cost_improve:.2%} below the selected baseline. Its unit fill rate is {oper['primary']['global_quantiles']['unit_fill_rate']:.2%}; seasonal naive’s is {oper['primary']['seasonal_naive']['unit_fill_rate']:.2%}. Lower penalty therefore does not mean highest service. None of these amounts is measured retailer savings or achieved commercial profit.",
        '', '## Data and information timing','',
        f"The M5 organizers’ public research/replication collection is mirrored by Nixtla. The sample is the first10 lexical item IDs per department, crossed with CA_1/TX_1/WI_1:210series,70items,7departments,1941daily observations from{audit['date_range'][0]} to{audit['date_range'][1]}. No sales or test-performance filter selects the sample. Source sales are nonnegative integer units; {audit['zero_fraction']:.2%} are zero. Zero sales may reflect intermittency, launch timing or stockouts; they are not identified latent demand.",
        '', 'Nixtla’s mirror omits the competition id/calendar d columns. The pipeline explicitly constructs item__store keys and sequential day labels; no unit values are changed. All ZIP members are read through CRC verification and hashed. The cached subset, source/member hashes and exact build recipe support recovery. Research/replication access does not establish an unrestricted raw-data redistribution or commercial-use license. Source observations are not relicensed as code.','',
        'Each forecast origin is the last observed day; the target is the following14days. Training origins364–1596, calibration1624–1715, development1743–1799 and final1827–1925 are all7days apart. Boundaries leave labels from each earlier phase before the next. Final14-day targets overlap; the operating simulator consumes nonoverlapping7-day review periods. The summed14-day target count is not a unique105-day sales total.','',
        'Only observed sales lags, deterministic date features, item/department/store IDs and the last completed-week price are used. Every origin is checked against the source price-week calendar so that the week’s average price is complete. No future realized prices, promotions, SNAP schedules or unknown events enter. Prices are forward-filled only, never backfilled. Model imputation uses the training median, with a missing-price flag; operational ordering never invents a missing procurement cost. All final-origin prices are observed.','',
        '## Fixed models and decision','',
        'Seasonal naive predicts twice the previous7-day total. Croston SBA uses alpha.1, initial positive size and the initial interval including preceding observed zeros; later updates occur only on positive sales. Each distributional baseline adds department-pooled calibration residual quantiles, scaled by max(last28day total/2,1). Calibration origins are separate from fitting/development/test.','',
        'The challenger has four direct global histogram gradient boosting models at quantiles.1/.5/.8/.9, with150iterations,15leaves,minimum50rows/leaf,learning_rate.08,L2=5,max_bins128 and no early stopping/search. Categorical vocabularies and price imputation are fixed from training. All models are fitted once; final forecasts update lagged observed features without refitting weights. Quantiles are sorted and clipped at zero before evaluation, as specified before fitting.','',
        f"Raw quantile crossing occurred in {dev['quantile_crossing_before_sort']['development']:.2%} of development and {dev['quantile_crossing_before_sort']['test']:.2%} of final forecasts. Reported scores and calibration are after the fixed coherence correction. No hierarchy reconciliation is performed.",
        '', 'Croston was selected among baselines by development pinball loss. The global challenger then beat that selected baseline on development and was frozen as the forecast choice. Final results do not switch the comparator to the test-best baseline or tune the challenger. Models, calibration, predictions, protocol and inputs are hash-guarded before final scoring.','',
        '| Model | Development pinball | Final pinball | Final median MAE | Final WAPE | 80% interval coverage | .8quantile empirical fraction |','|---|---:|---:|---:|---:|---:|---:|']
    for k,v in score.items():md.append(f"| {names[k]} | {dev['metrics'][k]['mean_pinball']:.4f} | {v['mean_pinball']:.4f} | {v['mae_median']:.4f} | {v['wape_median']:.2%} | {v['interval80_coverage']:.2%} | {v['q80_empirical_fraction_leq']:.2%} |")
    md+=['','The global80% interval covers88.98% in this discrete, zero-heavy sample; exact80% calibration is not established. The .8quantile covers78.38%. Inspect interval width and store/department diagnostics in final.json. Marginal interval coverage does not guarantee joint coverage or service levels. No official M5 leaderboard score/rank is claimed: this uses a different sample, horizon and scoring rule.','',
         '## Operating policy and constraints','',
         'Review weekly with one-week delivery delay. Order toward the forecast.8quantile of14-day sales, net of onhand and outstanding orders, using integer units. Start empty with no free stock. Receive the prior order at the next review; unmet sales are lost, not backlogged. Source sales serve as the demand proxy.','',
         'Assumed procurement cost is.6 times the last completed-week selling price; holding penalty.1 times that price per ending unit/week; lost-sales penalty.4 times it per missed unit. These costs, the delivery delay, budget and capacity are hypothetical. Procurement spend is separate from the penalty objective. Ending inventory/pipeline are reported, not converted into profit.','',
         'The budget is an exogenous multiplier of trailing28day average weekly procurement spend and is identical across models. Capacity is twice trailing weekly unit volume. Desired orders are allocated greedily by shortage-penalty/unit-cost, lower inventory coverage, then stableID. This is a fully specified constrained policy, not a globally optimal inventory allocation. No future demand enters its priorities.','',
         '| Scenario / model | Simulated penalty (USD) | Unit fill | Procurement spend (USD) | Ending stock | Ending pipeline |','|---|---:|---:|---:|---:|---:|']
    for s,models in oper.items():
        for k,v in models.items():md.append(f"| {s} / {names[k]} | {v['total_penalty']:,.2f} | {v['unit_fill_rate']:.2%} | {v['procurement_spend']:,.2f} | {v['ending_inventory_units']:,.2f} | {v['ending_pipeline_units']:,.0f} |")
    md+=['','All15weeks and post-startup penalties are retained in final.json. The first week starts empty, so all policies miss its demand; this is disclosed rather than hidden with free initial inventory. The two-week-lead-time scenario deliberately leaves the14-day policy target unchanged and is a misspecification stress, not a reoptimized policy. The censoring proxy increases zero-sale weeks’ demand by25% of trailing weekly sales; it cannot recover true stockouts. Shortage-cost and budget sensitivities retain their stated assumptions. The final operating rankings are descriptive and do not select a new model after seeing test outcomes.','',
         '## Verification and limits','',
         'Nine unit tests cover SBA known sequences, exact target boundaries, future sales/price feature invariance, quantile scoring/coherence, cash/capacity/integer constraints, missing-cost abstention, arrival delay, stock conservation, tighter budgets and censor/lead-time checks. Final verification recomputes all global predictions from the frozen model, bitwise-identical; reconciles pinball losses with scikit-learn; perturbs all future sales/prices at three final origins; and checks budgets, capacities and stock/pipeline conservation in all21 model/scenario runs. All eleven source/model freeze hashes pass before and after final scoring.','',
         'Bootstrap draws resample two-week origin blocks with all series together, not independent item rows. Fifteen origins and a fixed sample limit external validity; the interval conditions on training/calibration and does not include retraining or sample selection. Operational metrics are deterministic simulations, with no confidence interval claimed for an actual retailer. No observed stock, replenishment, costs or stockout labels are available.','',
         '## Recruiter explanation','',
         'Built a forecast-to-order pipeline with explicit information timing, four global quantile models, a locked future evaluation and dependence-aware uncertainty. Demonstrated why forecast accuracy, service and simulated cost can rank policies differently under common capital/capacity constraints. Added failure scenarios and an offline budget explorer; empirical sales and hypothetical operating assumptions remain distinct.','',
         '![Forecast and inventory diagnostics](diagnostics.svg)','',
         'Evidence: [data audit](data_audit.json), [development](development.json), [model freeze](model_freeze.json), [final results](final.json), [verification](verification.json), [protocol](../PROTOCOL.md). Public tagged release/live demo verification remain open.']
    (ROOT/'reports/TECHNICAL_REPORT.md').write_text('\n'.join(md)+'\n')
    (ROOT/'reports/DECISION_MEMO.md').write_text(f'''# Forecast-to-order decision memo

17 October2026 · Historical retail data and hypothetical operating costs

Retain the development-selected global quantile model for this research case. Final pinball loss is{improve:.2%} lower than the development-selected Croston baseline. The paired difference is {dec['paired_pinball_difference']:.4f}, 95% two-origin block interval [{dec['bootstrap95'][0]:.4f},{dec['bootstrap95'][1]:.4f}], conditional on the frozen models and only15weekly origins.

The operating objective changes the ranking among simple methods: seasonal naive forecasts better than Croston in the final period but incurs a greater simulated penalty. The global model has the lowest primary penalty, USD {oper['primary']['global_quantiles']['total_penalty']:,.2f}, while its{oper['primary']['global_quantiles']['unit_fill_rate']:.2%} fill rate is slightly below seasonal naive. The correct choice depends on explicit service/capital/cost priorities.

Do not present the penalty reduction as actual retailer savings. Costs, inventory starting empty, one-week lead time, loss treatment, cash budgets and greedy allocation are imposed assumptions. Zero sales are not proven unconstrained demand. Check the fixed lower/higher budget, longer lead-time, shortage-cost and censoring cases before generalizing. Procurements, terminal stock and pipeline are separately reported.

The next operational requirement is real stock, cost, delivery and lost-sales data. The current deliverable is a reproducible benchmark and policy simulator, with an offline explorer. It is not a deployed forecast/order system or an official M5 ranking. See [technical report](TECHNICAL_REPORT.md) and [fixed evidence](final.json).
''')
    plt.rcParams.update({'font.size':10});fig,axs=plt.subplots(1,3,figsize=(14,4),layout='constrained');keys=list(names)
    labels=['Seasonal','Croston','Global'];colors=['#94A3B8','#A86735','#193B58']
    axs[0].bar(labels,[score[k]['mean_pinball'] for k in keys],color=colors);axs[0].set(title='Final forecast score',ylabel='Mean pinball loss (units)')
    axs[1].bar(labels,[oper['primary'][k]['total_penalty'] for k in keys],color=colors);axs[1].set(title='Primary inventory scenario',ylabel='Simulated penalty (USD)')
    for k,color in zip(keys,colors):axs[2].plot([.5,1,2],[100*oper[s][k]['unit_fill_rate'] for s in ['budget_half','primary','budget_double']],marker='o',label=names[k].split(' +')[0],color=color)
    axs[2].set(title='Capital and service',xlabel='Common budget multiplier',ylabel='Unit fill rate (%)');axs[2].legend(fontsize=8)
    for ax in axs:ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
    fig.savefig(ROOT/'reports/diagnostics.svg');fig.savefig(ROOT/'reports/diagnostics.png',dpi=140);plt.close(fig)
    # Only aggregate scores and derived order recommendations enter the offline demo.
    demo={'models':names,'forecast':score,'selection':dec,'scenarios':{},'orders':{},'affected':{}}
    for s in ['budget_half','primary','budget_double']:
        demo['scenarios'][s]={k:{f:v[f] for f in ['total_penalty','unit_fill_rate','procurement_spend','ending_inventory_units','ending_pipeline_units','rows']} for k,v in oper[s].items()}
    for k in names:
        half=d['first_order_vectors']['budget_half'][k];double=d['first_order_vectors']['budget_double'][k]
        affected=[j for j in range(len(half)) if half[j]!=double[j]][:15];demo['affected'][k]=[d['series_ids'][j] for j in affected]
        demo['orders'][k]={s:[d['first_order_vectors'][s][k][j] for j in affected] for s in ['budget_half','primary','budget_double']}
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forecasts and inventory decisions | Prasanna K</title><style>body{font:16px/1.55 system-ui,sans-serif;color:#172b3b;background:#f5f7fa;margin:0}main{max-width:1060px;margin:auto;padding:30px 22px}h1{font-size:32px;line-height:1.2}h2{font-size:22px}p{max-width:900px}label{display:inline-block;margin:0 25px 15px 0}select{display:block;padding:10px;font:inherit;max-width:100%}.metrics{display:flex;gap:15px;flex-wrap:wrap}.metric{background:white;padding:18px;border:1px solid #cbd5e1;min-width:180px}.metric strong{display:block;font-size:25px}.note{border-left:4px solid #a86735;padding:8px 15px;background:#fff8ee}.table{overflow-x:auto}.table:focus-visible{outline:3px solid #418780;outline-offset:3px}table{border-collapse:collapse;width:100%;background:white}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid #dce2e8}th{background:#193b58;color:white}a{color:#193b58}button,select:focus{outline:2px solid #418780}footer{font-size:14px;margin-top:25px;color:#425466}@media(max-width:600px){main{padding:22px 16px}label{display:block;max-width:100%;margin:0 0 16px}select{width:100%;box-sizing:border-box}.metric{box-sizing:border-box;min-width:0;flex:1 1 100%}}</style></head><body><main><p>Prasanna K · Retail demand and constrained ordering</p><h1>Better forecasts need an operating decision.</h1><p>A frozen historical comparison on 210 M5 series. Choose a model and a common capital limit to inspect the precomputed policy simulation.</p><p class="note">Costs, lead time, stock and capital rules are hypothetical. Sales are a demand proxy. Amounts below are simulated penalties and procurement spend, not measured savings.</p><label>Forecast model<select id="model"></select></label><label>Capital budget<select id="budget"><option value="budget_half">0.5 × trailing weekly spend</option><option value="primary" selected>1.0 × trailing weekly spend</option><option value="budget_double">2.0 × trailing weekly spend</option></select></label><section aria-live="polite"><div class="metrics"><div class="metric">Simulated penalty (USD)<strong id="penalty"></strong></div><div class="metric">Unit fill rate<strong id="fill"></strong></div><div class="metric">Procurement spend (USD)<strong id="spend"></strong></div><div class="metric">Ending stock / pipeline<strong id="stock"></strong></div></div><h2>Orders affected by capital limits</h2><p>The first review starts empty. These model-derived integer order quantities belong to the same observed decision date. Pending orders arrive one week later. Items shown are those whose orders differ between half and double budget.</p><p id="first"></p><div class="table" tabindex="0" role="region" aria-label="Order quantity comparisons"><table><thead><tr><th>Series</th><th>Half budget</th><th>Base budget</th><th>Double budget</th></tr></thead><tbody id="orders"></tbody></table></div><h2>Forecast evidence</h2><p id="forecast"></p></section><footer>15 weekly final origins. Two-origin block uncertainty preserves item/store dependence. No model refit or calibration occurs in this page. All controls select saved scenarios. <a href="exports/technical_report.html">Technical report</a> · <a href="exports/decision_memo.html">Decision memo</a></footer></main><script id="evidence" type="application/json">EVIDENCE_JSON</script><script>const DATA=JSON.parse(document.getElementById('evidence').textContent);const model=document.getElementById('model'),budget=document.getElementById('budget');Object.entries(DATA.models).forEach(([value,text])=>{const o=document.createElement('option');o.value=value;o.textContent=text;model.appendChild(o)});model.value=DATA.selection.development_selected_forecast;const money=x=>x.toLocaleString('en-US',{maximumFractionDigits:2,minimumFractionDigits:2});function render(){const k=model.value,s=budget.value,r=DATA.scenarios[s][k];document.getElementById('penalty').textContent=money(r.total_penalty);document.getElementById('fill').textContent=(100*r.unit_fill_rate).toFixed(2)+'%';document.getElementById('spend').textContent=money(r.procurement_spend);document.getElementById('stock').textContent=r.ending_inventory_units.toFixed(0)+' / '+r.ending_pipeline_units.toFixed(0);const f=r.rows[0];document.getElementById('first').textContent='First review: '+f.ordered_units+' units ordered; USD'+money(f.procurement_spend)+' spent within USD'+money(f.budget)+' common budget.';const body=document.getElementById('orders');body.innerHTML='';DATA.affected[k].forEach((id,j)=>{const tr=document.createElement('tr');[id,...['budget_half','primary','budget_double'].map(z=>DATA.orders[k][z][j])].forEach(text=>{const td=document.createElement('td');td.textContent=text;tr.appendChild(td)});body.appendChild(tr)});const z=DATA.forecast[k];document.getElementById('forecast').textContent='Mean pinball loss '+z.mean_pinball.toFixed(4)+'. Median MAE '+z.mae_median.toFixed(4)+'. Nominal 80% interval coverage '+(100*z.interval80_coverage).toFixed(2)+'%. Scores use overlapping 14-day targets; inventory uses separate 7-day periods.';}model.addEventListener('change',render);budget.addEventListener('change',render);render();</script></body></html>'''
    (ROOT/'docs').mkdir(exist_ok=True);(ROOT/'docs/index.html').write_text(html.replace('EVIDENCE_JSON',json.dumps(demo,separators=(',',':')).replace('</','<\\/')))
    print('Technical report, decision memo, figure and offline explorer generated')

if __name__=='__main__':
    run()
    from format_prose import polish
    for document in list(ROOT.glob('README.md'))+list((ROOT/'reports').glob('*.md'))+list((ROOT/'docs').glob('*.md')):
        document.write_text(polish(document.read_text()))
